package com.kaipai.service.ai.impl;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*; import com.fasterxml.jackson.databind.ObjectMapper; import com.kaipai.mapper.ai.*; import com.kaipai.model.ai.dto.*; import com.kaipai.model.ai.entity.AiProfileImportConfig; import com.kaipai.service.ai.*; import org.junit.jupiter.api.*;
class ProfileImportConfigServiceImplTest { private AiProfileImportConfigMapper mapper; private AiProfileImportConfigAuditMapper auditMapper; private AiProviderSecretCryptoService crypto; private ProfileImportConnectionTester tester; private ProfileImportConfigServiceImpl service; private AiProfileImportConfig stored; @BeforeEach void setup(){mapper=mock(AiProfileImportConfigMapper.class);auditMapper=mock(AiProfileImportConfigAuditMapper.class);crypto=mock(AiProviderSecretCryptoService.class);tester=mock(ProfileImportConnectionTester.class);stored=new AiProfileImportConfig();stored.setConfigId(1L);stored.setProviderCode("deepseek");when(mapper.selectOne(any())).thenAnswer(c->stored);when(mapper.updateById(any())).thenAnswer(c->{stored=c.getArgument(0);return 1;});service=new ProfileImportConfigServiceImpl(mapper,auditMapper,crypto,tester,new ObjectMapper());}
 @Test void secretIsEncryptedAndReadBackOnlyAsMask(){when(crypto.encrypt(any())).thenReturn("ciphertext");var result=service.saveSecret(9L,new ProfileImportSecretUpdateDTO("sk-test"));assertEquals("****test",result.getSecretMask());assertFalse(result.toString().contains("sk-test"));assertEquals("ciphertext",stored.getSecretConfigCiphertext());}
 @Test void capabilityRequiresConfigSecretSuccessfulTestAndEnable(){service.savePublicConfig(9L,valid());assertFalse(service.capability().isAvailable());when(crypto.encrypt(any())).thenReturn("cipher");service.saveSecret(9L,new ProfileImportSecretUpdateDTO("sk-test"));when(crypto.decrypt("cipher")).thenReturn("{\"apiKey\":\"sk-test\"}");service.testConnection(9L);service.setEnabled(9L,true);assertTrue(service.capability().isAvailable());verify(auditMapper,atLeast(2)).insert(any());}
 private ProfileImportPublicConfigUpdateDTO valid(){var d=new ProfileImportPublicConfigUpdateDTO();d.setEndpoint("https://api.deepseek.com/chat/completions");d.setModelName("deepseek-chat");d.setConnectTimeoutMs(3000);d.setReadTimeoutMs(30000);d.setMaxInputChars(20000);d.setMaxOutputTokens(8000);d.setPerUserDailyLimit(10);return d;} }
